package com.bank.codepad.service;

import java.util.logging.Logger;

// Min insertions to palindrome = length - longest palindromic subsequence.
public class CodePaddingService {
    private static final Logger log = Logger.getLogger(CodePaddingService.class.getName());

    public int minInsertions(String code) {
        int n = code.length();
        int[][] dp = new int[n][n];                 // longest palindromic subsequence table
        for (int i = n - 1; i >= 0; i--) {
            dp[i][i] = 1;
            for (int j = i + 1; j < n; j++) {
                if (code.charAt(i) == code.charAt(j))
                    dp[i][j] = 2 + dp[i + 1][j - 1]; // matched ends need no insertion
                else
                    dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);
            }
        }
        int lps = n == 0 ? 0 : dp[0][n - 1];
        final int r = n - lps;                      // each unmatched char needs a mirror
        log.info(() -> "Min insertions to make " + code + " a palindrome = " + r);
        return r;
    }
}
