package com.bank.codepad;

import com.bank.codepad.service.CodePaddingService;
import java.util.logging.Logger;

public class CodePaddingApplication {
    private static final Logger log = Logger.getLogger(CodePaddingApplication.class.getName());

    public static void main(String[] args) {
        CodePaddingService service = new CodePaddingService();
        String code = "ABCDA";
        int insertions = service.minInsertions(code);
        log.info("Insertions to canonicalise code " + code + " is " + insertions);
    }
}
